#ifndef SOFDEC_MPVIDCT_PPC_H
#define SOFDEC_MPVIDCT_PPC_H

#include "types.h"

/* CRI Sofdec MPEG inverse DCT, the paired-single kernels of movie_module fn_12_4F3C.
 *
 * These are inline assembly on the caller's register variables: the update forms psq_lu / psq_stu and
 * ps_sel are never generated by MWCC from C. The compiler allocates the registers and schedules the
 * instructions, so the caller declares the variables in the order that gives retail's registers.
 * Both passes carry their own loop control: with the decrement written in C the counter cannot take r0,
 * which retail uses. They are macros, expanded inside the caller, like the quantised kernels in
 * psvec_quant.h; a macro is one logical line, hence the ';' after each instruction. */

/* The six constant pairs of the transform, loaded from the table at kp (which is advanced). */
#define MPVIDCT_LOAD_CONSTANTS(kp, k1, k2, k3, k4, k5, k6) \
    asm { \
        psq_lu k1, 0(kp), 0, 0; \
        psq_lu k2, 8(kp), 0, 0; \
        psq_lu k3, 8(kp), 0, 0; \
        psq_lu k4, 8(kp), 0, 0; \
        psq_lu k5, 8(kp), 0, 0; \
        psq_lu k6, 8(kp), 0, 0; \
    }

/* First pass, n = 4 column pairs: eight pairs are read from p (pre-incremented), transformed, and the
 * results are stored through q transposed (ps_merge00 / ps_merge11). */
#define MPVIDCT_PASS1(p, q, n, k1, k2, k3, k4, t0, t7, t8, t9, t10, t11, t12, t13, t31) \
    asm { \
        pass1: \
        psq_lu t0, 8(p), 0, 0; \
        psq_lu t7, 8(p), 0, 0; \
        psq_lu t8, 8(p), 0, 0; \
        psq_lu t9, 8(p), 0, 0; \
        psq_lu t10, 8(p), 0, 0; \
        psq_lu t11, 8(p), 0, 0; \
        psq_lu t12, 8(p), 0, 0; \
        psq_lu t13, 8(p), 0, 0; \
        ps_sub t31, t8, t12; \
        ps_add t12, t8, t12; \
        ps_sub t8, t0, t10; \
        ps_mul t31, t31, k1; \
        ps_add t10, t0, t10; \
        ps_sub t31, t31, t12; \
        ps_sub t0, t10, t12; \
        ps_add t12, t10, t12; \
        ps_sub t10, t8, t31; \
        ps_add t31, t8, t31; \
        ps_sub t8, t11, t9; \
        ps_add t9, t11, t9; \
        ps_sub t11, t7, t13; \
        ps_add t13, t7, t13; \
        ps_sub t7, t13, t9; \
        ps_add t9, t13, t9; \
        ps_sub t13, t8, t11; \
        ps_mul t11, t11, k3; \
        ps_mul t8, t8, k2; \
        ps_mul t13, t13, k4; \
        ps_mul t7, t7, k1; \
        ps_sub t11, t11, t13; \
        ps_sub t8, t8, t13; \
        ps_sub t13, t12, t9; \
        ps_sub t11, t11, t9; \
        ps_add t9, t12, t9; \
        ps_sub t7, t7, t11; \
        ps_sub t12, t31, t11; \
        ps_add t11, t31, t11; \
        ps_sub t8, t8, t7; \
        ps_sub t31, t0, t8; \
        ps_add t8, t0, t8; \
        ps_sub t0, t10, t7; \
        ps_add t7, t10, t7; \
        ps_merge00 t10, t9, t11; \
        psq_stu t10, 8(q), 0, 0; \
        ps_merge00 t10, t7, t8; \
        psq_stu t10, 8(q), 0, 0; \
        ps_merge00 t10, t31, t0; \
        psq_stu t10, 8(q), 0, 0; \
        ps_merge00 t10, t12, t13; \
        psq_stu t10, 8(q), 0, 0; \
        ps_merge11 t10, t9, t11; \
        psq_stu t10, 8(q), 0, 0; \
        ps_merge11 t10, t7, t8; \
        psq_stu t10, 8(q), 0, 0; \
        ps_merge11 t10, t31, t0; \
        psq_stu t10, 8(q), 0, 0; \
        ps_merge11 t10, t12, t13; \
        subic. n, n, 1; \
        psq_stu t10, 8(q), 0, 0; \
        bgt pass1; \
    }

/* Second pass, n = 4 row pairs: eight pairs are read from p in steps of 0x20, transformed, rounded with
 * ps_sel (k5 / k6 by sign) and stored through q as quantised pairs (GQR7), one output row each. */
#define MPVIDCT_PASS2(p, q, n, k1, k2, k3, k4, k5, k6, t0, t7, t8, t9, t10, t11, t12, t13, t31) \
    asm { \
        pass2: \
        psq_lu t0, 0(p), 0, 0; \
        psq_lu t11, 32(p), 0, 0; \
        psq_lu t12, 32(p), 0, 0; \
        psq_lu t9, 32(p), 0, 0; \
        psq_lu t31, 32(p), 0, 0; \
        psq_lu t8, 32(p), 0, 0; \
        psq_lu t13, 32(p), 0, 0; \
        psq_lu t7, 32(p), 0, 0; \
        ps_sub t10, t12, t13; \
        ps_add t13, t12, t13; \
        ps_sub t12, t0, t31; \
        ps_mul t10, t10, k1; \
        ps_add t31, t0, t31; \
        ps_sub t10, t10, t13; \
        ps_sub t0, t31, t13; \
        ps_add t13, t31, t13; \
        ps_sub t31, t12, t10; \
        ps_add t10, t12, t10; \
        ps_sub t12, t8, t9; \
        ps_add t9, t8, t9; \
        ps_sub t8, t11, t7; \
        ps_add t7, t11, t7; \
        ps_sub t11, t7, t9; \
        ps_add t9, t7, t9; \
        ps_sub t7, t12, t8; \
        ps_mul t8, t8, k3; \
        ps_mul t12, t12, k2; \
        ps_mul t7, t7, k4; \
        ps_mul t11, t11, k1; \
        ps_sub t8, t8, t7; \
        ps_sub t12, t12, t7; \
        ps_sub t7, t13, t9; \
        ps_sub t8, t8, t9; \
        ps_add t9, t13, t9; \
        ps_sub t11, t11, t8; \
        ps_sub t13, t10, t8; \
        ps_add t8, t10, t8; \
        ps_sub t12, t12, t11; \
        ps_sub t10, t0, t12; \
        ps_add t12, t0, t12; \
        ps_sub t0, t31, t11; \
        ps_add t11, t31, t11; \
        ps_sel t31, t9, k5, k6; \
        ps_add t9, t9, t31; \
        ps_sel t31, t8, k5, k6; \
        ps_add t8, t8, t31; \
        ps_sel t31, t11, k5, k6; \
        ps_add t11, t11, t31; \
        psq_stu t9, 0(q), 0, 7; \
        ps_sel t31, t12, k5, k6; \
        ps_add t12, t12, t31; \
        psq_stu t8, 16(q), 0, 7; \
        ps_sel t31, t10, k5, k6; \
        psq_stu t11, 16(q), 0, 7; \
        ps_add t10, t10, t31; \
        psq_stu t12, 16(q), 0, 7; \
        ps_sel t31, t0, k5, k6; \
        ps_add t0, t0, t31; \
        ps_sel t31, t13, k5, k6; \
        psq_stu t10, 16(q), 0, 7; \
        ps_add t13, t13, t31; \
        psq_stu t0, 16(q), 0, 7; \
        ps_sel t31, t7, k5, k6; \
        psq_stu t13, 16(q), 0, 7; \
        ps_add t7, t7, t31; \
        subic. n, n, 1; \
        psq_stu t7, 16(q), 0, 7; \
        ble pass2_end; \
        subi p, p, 216; \
        subi q, q, 108; \
        b pass2; \
        pass2_end: \
    }

#endif
